[
  {
    "statement": "The action documents do not contain direct cost-effectiveness comparisons between providing supplementary food and sowing wild bird seed mixtures for increasing farmland bird populations.",
    "citations": []
  },
  {
    "statement": "Both providing supplementary food and sowing wild bird seed mixtures show evidence of effectiveness for bird populations.",
    "citations": []
  },
  {
    "statement": "Nine studies from France, Sweden and the UK found that supplementary food increased farmland bird abundance, breeding population size, density, body mass, hatching, nestling growth and fledging rates.",
    "citations": [
      "648"
    ]
  },
  {
    "statement": "Nine studies from France, Sweden and the UK found that supplementary food increased overwinter survival of declining house sparrow populations.",
    "citations": [
      "648"
    ]
  },
  {
    "statement": "Five studies found supplementary food had no clear effect on farmland bird breeding abundance, reproductive success, territory size or density.",
    "citations": [
      "648"
    ]
  },
  {
    "statement": "Five studies found supplementary food had no clear effect on the overwinter survival of stable house sparrow populations.",
    "citations": [
      "648"
    ]
  },
  {
    "statement": "Thirty individual studies investigated the effects of wild bird seed or cover mixtures, with 21 of those studies finding positive effects.",
    "citations": [
      "594",
      "187"
    ]
  },
  {
    "statement": "Fourteen studies from the UK found that fields sown with a wild bird cover mix had higher abundance, density, species diversity and species richness of birds than other farmland habitats.",
    "citations": [
      "594",
      "187"
    ]
  },
  {
    "statement": "All seven studies from the UK found that fields or farms with wild bird cover had higher bird diversity than those without wild bird cover.",
    "citations": [
      "594",
      "187"
    ]
  },
  {
    "statement": "Thirty-two out of 33 studies from the UK and North America found that bird densities, abundances, nesting densities or use of wild bird cover was higher than in other habitats.",
    "citations": [
      "594",
      "187"
    ]
  },
  {
    "statement": "Agri-environment schemes, which can include both providing supplementary food and sowing wild bird seed mixtures, involve paying farmers to cover conservation costs.",
    "citations": [
      "172",
      "700"
    ]
  },
  {
    "statement": "Specific cost comparisons between supplementary feeding and wild bird seed mixtures are not provided in the available evidence.",
    "citations": []
  }
]

[
  {
    "statement": "Studies from Canada and the USA examining beetle banks found mixed effectiveness for conserving native predator insects in agricultural systems, including soybean fields.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "Six studies from Canada and the USA examined predator numbers in adjacent crops.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "A review found that predators increased in crops adjacent to beetle banks.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "One study found that the effects of beetle banks on predator numbers varied with time.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "Another study found that beetle banks had no effect on predator numbers.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "Four studies and a review found more invertebrate predators on beetle banks than in surrounding crops.",
    "citations": []
  },
  {
    "statement": "Soybean crops were among the crops found to have fewer invertebrate predators than adjacent beetle banks.",
    "citations": []
  },
  {
    "statement": "Two studies found that the movements of predators from beetle banks to crops were small or slow.",
    "citations": []
  },
  {
    "statement": "One study found greater beetle activity in fields with beetle banks, but this activity did not improve pest predation.",
    "citations": []
  },
  {
    "statement": "An economic analysis indicated that beetle banks could create economic savings if the beetle banks prevented pests from reaching a spray threshold.",
    "citations": []
  },
  {
    "statement": "An economic analysis indicated that beetle banks could create economic savings if the beetle banks prevented pests from causing a 5% yield loss.",
    "citations": []
  },
  {
    "statement": "Studies showed that certain grass species used in beetle banks held higher numbers of predatory invertebrates than other grass species.",
    "citations": []
  },
  {
    "statement": "The design considerations of beetle banks, such as the choice of grass species, affect the effectiveness of the beetle banks.",
    "citations": []
  }
]

[
  {
    "statement": "Based on available evidence, marking fencing appears to have more documented effectiveness than avoiding lead shot for protecting farmland birds from mortality.",
    "citations": []
  },
  {
    "statement": "A randomised, replicated and controlled study from the UK found that fewer birds collided with deer fence marked with orange netting than with unmarked sections of fence.",
    "citations": [
      "238"
    ]
  },
  {
    "statement": "There is no evidence captured for the effects of marking fencing to avoid bird mortality specifically on farmland wildlife.",
    "citations": [
      "706"
    ]
  },
  {
    "statement": "No evidence has been captured for the effects of avoiding the use of lead shot on farmland wildlife.",
    "citations": [
      "100"
    ]
  },
  {
    "statement": "Marking power lines led to significant reductions in collision rates in multiple studies.",
    "citations": [
      "265"
    ]
  },
  {
    "statement": "The specific farmland context lacks comprehensive evidence for the effectiveness of both marking fencing and avoiding lead shot.",
    "citations": []
  }
]
